import os
from pathlib import Path

import pytest


def read_note(name: str) -> str:
    """Return the UTF-8 text of the file `name` inside the `notes` directory.

    `notes` is resolved relative to the current working directory, and `name`
    is untrusted. `name` may be a plain file name or a relative path to a file
    in a subdirectory of `notes`. The file that is actually read, after
    resolving `..` components, absolute paths and symlinks, must lie inside
    `notes`.

    Returns "" if the file is missing, is not a regular file, cannot be read
    or decoded, or if `name` is empty, contains a NUL byte, is absolute, or
    would reach anything outside `notes`. Never raises for any `str` input.
    """
    if not name or "\x00" in name:
        return ""
    try:
        rel = Path(name)
        if rel.is_absolute() or rel.anchor or rel.drive:
            return ""
        base = Path("notes").resolve()
        target = (base / rel).resolve()
        if not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError, UnicodeError):
        return ""


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "sub").mkdir()
    (notes / "sub" / "b.txt").write_text("nested", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_file(sandbox: Path) -> None:
    assert read_note("a.txt") == "hello"


def test_reads_nested_file(sandbox: Path) -> None:
    assert read_note("sub/b.txt") == "nested"


def test_missing_file_is_empty(sandbox: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name_is_empty(sandbox: Path) -> None:
    assert read_note("") == ""


def test_directory_is_empty(sandbox: Path) -> None:
    assert read_note("sub") == ""
    assert read_note(".") == ""


def test_parent_traversal_blocked(sandbox: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("..") == ""
    assert read_note("a.txt/../../secret.txt") == ""


def test_absolute_path_blocked(sandbox: Path) -> None:
    assert read_note(str(sandbox / "secret.txt")) == ""
    assert read_note(str(sandbox / "notes" / "a.txt")) == ""


def test_sibling_directory_with_same_prefix_blocked(sandbox: Path) -> None:
    evil = sandbox / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("evil", encoding="utf-8")
    assert read_note("../notes_evil/x.txt") == ""


def test_symlink_file_escaping_blocked(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_note("link.txt") == ""


def test_symlink_dir_escaping_blocked(sandbox: Path) -> None:
    link = sandbox / "notes" / "out"
    try:
        link.symlink_to(sandbox, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_note("out/secret.txt") == ""


def test_symlink_inside_notes_allowed(sandbox: Path) -> None:
    link = sandbox / "notes" / "alias.txt"
    try:
        link.symlink_to(sandbox / "notes" / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_note("alias.txt") == "hello"


def test_nul_byte_blocked(sandbox: Path) -> None:
    assert read_note("a.txt\x00../secret.txt") == ""
    assert read_note("\x00") == ""


def test_undecodable_file_is_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "bin.dat").write_bytes(b"\xff\xfe\xfa")
    assert read_note("bin.dat") == ""


@pytest.mark.skipif(not hasattr(os, "chmod") or os.name == "nt", reason="posix only")
def test_unreadable_file_is_empty(sandbox: Path) -> None:
    p = sandbox / "notes" / "locked.txt"
    p.write_text("x", encoding="utf-8")
    p.chmod(0)
    try:
        if os.access(p, os.R_OK):
            pytest.skip("running with privileges that ignore permissions")
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o600)


def test_very_long_name_is_empty(sandbox: Path) -> None:
    assert read_note("a" * 10000) == ""
